-- Cấu trúc Database và Dữ liệu mẫu (MySQL)
SET NAMES utf8mb4;
SET CHARACTER SET utf8mb4;

CREATE DATABASE IF NOT EXISTS school_db 
CHARACTER SET utf8mb4 
COLLATE utf8mb4_unicode_ci;

USE school_db;

CREATE TABLE Students (
    student_id VARCHAR(11) PRIMARY KEY,
    full_name VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE Subjects (
    subject_id INT PRIMARY KEY,
    subject_name VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE Schedules (
    schedule_id INT PRIMARY KEY AUTO_INCREMENT,
    student_id VARCHAR(11),
    subject_id INT,
    day_of_week INT,
    start_time TIME,
    room VARCHAR(10),
    FOREIGN KEY (student_id) REFERENCES Students(student_id),
    FOREIGN KEY (subject_id) REFERENCES Subjects(subject_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE Exams (
    exam_id INT PRIMARY KEY AUTO_INCREMENT,
    student_id VARCHAR(11),
    subject_id INT,
    exam_date DATE,
    start_time TIME,
    room VARCHAR(10),
    FOREIGN KEY (student_id) REFERENCES Students(student_id),
    FOREIGN KEY (subject_id) REFERENCES Subjects(subject_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

